81	// Kurz-Typ aus dem FQ-Namen: alles vor einem eventuellen '<', dann hinter dem letzten "::".
82	[[nodiscard]] std::string short_name(std::string const& fq) {
83	    std::size_t const lt   = fq.find('<');
84	    std::string const head = (lt == std::string::npos) ? fq : fq.substr(0, lt);
85	    std::size_t const cc   = head.rfind("::");
86	    return (cc == std::string::npos) ? head : head.substr(cc + 2);
87	}
