89	[[nodiscard]] std::string xml_escape(std::string const& s) {
90	    std::string o;
91	    o.reserve(s.size());
92	    for (char const c : s) {
93	        switch (c) {
94	            case '&': o += "&amp;"; break;
95	            case '<': o += "&lt;"; break;
96	            case '>': o += "&gt;"; break;
97	            case '"': o += "&quot;"; break;
98	            case '\'': o += "&apos;"; break;
99	            default: o += c;
100	        }
101	    }
102	    return o;
103	}
