117	// Reflektiert eine Enabled*-mp_list in ihre Bausteine (name/FQ-Typ/Kurz-Typ) + markiert golden anhand
118	// der ersten GoldenK Eintraege derselben Liste (== FullSourceCatalog-Take). mp_identity vermeidet die
119	// Default-Konstruktion der Wrapper (nur der Typ wird benoetigt).
120	template <class List, std::size_t GoldenK>
121	[[nodiscard]] std::vector<Baustein> reflect_axis() {
122	    constexpr std::size_t kSize = mp::mp_size<List>::value;
123	    constexpr std::size_t kTake = (GoldenK < kSize) ? GoldenK : kSize;
124	
125	    std::set<std::string> golden;
126	    mp::mp_for_each<mp::mp_transform<mp::mp_identity, mp::mp_take_c<List, kTake>>>([&](auto id) {
127	        using W = typename decltype(id)::type;
128	        golden.insert(std::string{W::name()});
129	    });
130	
131	    std::vector<Baustein> out;
132	    mp::mp_for_each<mp::mp_transform<mp::mp_identity, List>>([&](auto id) {
133	        using W = typename decltype(id)::type;
134	        Baustein b;
135	        b.name    = std::string{W::name()};
136	        b.type    = std::string{cg::type_name<W>()};
137	        b.wrapper = short_name(b.type);
138	        b.header  = organ_header<W>();
139	        b.golden  = golden.contains(b.name);
140	        out.push_back(std::move(b));
141	    });
142	    return out;
143	}
