2	// V41.F.6.1 R5.G — constexpr type_name<T>(): fully-qualified C++-Typ-Name als string_view zur Compile-Time.
3	//
4	// Grundlage des R5.G-AUTO-EMITTERS: der Generator iteriert via for_each_composition_type die
5	// enumerierten Permutationen und braucht pro Achsen-Vendor-Typ dessen FULLY-QUALIFIED C++-Typ-Namen
6	// als STRING, um ein Modul-.cpp mit COMDARE_DEFINE_ANATOMY_MODULE_ADHOC(<17 Typ-Namen>) zu emittieren.
7	//
8	// Technik (nameof-Pattern): der Compiler-Funktions-Signatur-String (__FUNCSIG__ / __PRETTY_FUNCTION__)
9	// enthält den Template-Typ; Prefix/Suffix werden an einem Probe-Typ (double) kalibriert + abgeschnitten.
10	// MSVC rendert Klassen als "class NS::T" → führendes "class "/"struct "/"enum " wird entfernt, sodass
11	// der reine FQ-Name (NS::T) für Codegen nutzbar ist.
12	
13	#include <string_view>
14	
15	namespace comdare::cache_engine::builder::codegen {
16	
17	namespace detail {
18	
19	template <class T>
20	[[nodiscard]] constexpr std::string_view raw_signature() noexcept {
21	#if defined(_MSC_VER)
22	    return __FUNCSIG__;
23	#else
24	    return __PRETTY_FUNCTION__;
25	#endif
26	}
27	
28	// Kalibrierung an einem Probe-Typ ("double" — 6 Zeichen, in jeder Signatur identisch gerendert).
29	inline constexpr std::string_view kProbe     = raw_signature<double>();
30	inline constexpr std::size_t      kProbePos  = kProbe.find("double");
31	inline constexpr std::size_t      kPrefixLen = kProbePos;
32	inline constexpr std::size_t      kSuffixLen = kProbe.size() - kProbePos - 6; // 6 == len("double")
33	
34	/// Entfernt ein führendes Elaborated-Type-Specifier-Keyword (MSVC: "class "/"struct "/"enum ").
35	/// HINWEIS (2026-06-03): schält NUR den ÄUSSEREN Specifier. MSVC rendert in __FUNCSIG__ auch verschachtelte
36	/// Template-Argumente mit "class "/"struct "-Prefix (z.B. `Outer<class NS::Inner>`); die INNEN-liegenden Keywords
37	/// bleiben hier stehen und werden host-seitig vom Emitter entfernt (adhoc_emitter.hpp strip_all_elaborated, der
38	/// einzige Konsument, der den Namen in echten C++-Quelltext schreibt). type_name() selbst bleibt unverändert
39	/// (constexpr-string_view, kein Heap/Lifetime-Risiko).
40	[[nodiscard]] constexpr std::string_view strip_elaborated(std::string_view s) noexcept {
41	    for (std::string_view kw : {std::string_view{"class "}, std::string_view{"struct "}, std::string_view{"enum "},
42	                                std::string_view{"union "}}) {
43	        if (s.substr(0, kw.size()) == kw) return s.substr(kw.size());
44	    }
45	    return s;
46	}
47	
48	} // namespace detail
49	
50	/// type_name<T>() — fully-qualified Typ-Name von T (Compile-Time, ohne FÜHRENDEN "class/struct"-Prefix).
51	template <class T>
52	[[nodiscard]] constexpr std::string_view type_name() noexcept {
53	    std::string_view s = detail::raw_signature<T>();
54	    s.remove_prefix(detail::kPrefixLen);
55	    s.remove_suffix(detail::kSuffixLen);
56	    return detail::strip_elaborated(s);
57	}
58	
59	} // namespace comdare::cache_engine::builder::codegen
